#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Carga en GitHub los cuatro secrets de firma que usa .github/workflows/apk.yml,
# bajando el keystore que EAS ya tiene para la app. Los valores van directo de
# EAS a `gh secret set` por entrada estándar: nunca se muestran ni se copian.
#
# Se corre desde la raíz del repositorio, en Git Bash:
#
#   bash scripts/cargar-keystore.sh
#
# Guía completa y alternativa manual: docs/compilar-apk.md.

# Archivos que deja `eas credentials`. Se borran al salir aunque el script se
# corte a mitad (ver _limpiar_al_salir).
CREDENCIALES_JSON="credentials.json"
KEYSTORE_EAS=""          # ruta del .jks que bajó EAS (de credentials.json)
KEYSTORE_MANUAL=""       # ruta del .jks que indicó la persona (camino manual)
_LIMPIEZA_ACTIVA=0       # 1 desde que puede haber archivos de EAS por borrar
_CONSERVAR_ARCHIVOS=0    # 1 si la persona eligió no borrarlos en la etapa 5

# Borra credentials.json, el keystore que bajó EAS y la carpeta credentials/
# si quedó vacía.
_borrar_credenciales_eas() {
  rm -f "$CREDENCIALES_JSON"
  if [[ -n "$KEYSTORE_EAS" ]]; then
    rm -f "$KEYSTORE_EAS"
  fi
  if [[ -d credentials ]]; then
    find credentials -depth -type d -empty -delete 2>/dev/null || true
  fi
}

# Trampa de salida: si el script se corta después de bajar las credenciales,
# no quedan el keystore ni sus contraseñas en disco.
# shellcheck disable=SC2329  # se invoca desde `trap ... EXIT`
_limpiar_al_salir() {
  if (( _LIMPIEZA_ACTIVA )) && (( ! _CONSERVAR_ARCHIVOS )); then
    # El keystore se busca también acá: el corte pudo ser antes de leerlo.
    if [[ -z "$KEYSTORE_EAS" && -f "$CREDENCIALES_JSON" ]]; then
      KEYSTORE_EAS=$(leer_credencial keystorePath 2>/dev/null || true)
    fi
    _borrar_credenciales_eas
  fi
}

# leer_credencial CAMPO escribe por stdout android.keystore.CAMPO de
# credentials.json, sin salto de línea. Falla si el campo falta o está vacío.
leer_credencial() {
  node -e '
    const fs = require("fs");
    const c = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
    const k = (c.android && c.android.keystore) || {};
    const v = k[process.argv[1]];
    if (typeof v !== "string" || v === "") process.exit(1);
    process.stdout.write(v);
  ' "$1" "$CREDENCIALES_JSON"
}

# Nombres exactos de los secrets que lee apk.yml.
SECRETS_APK=(ANDROID_KEYSTORE_BASE64 ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD)

run_wizard() {

TOTAL_STAGES=5

trap _limpiar_al_salir EXIT
# Ctrl-C o un cierre de la terminal terminan el script por `exit`, que dispara
# la trampa de salida.
trap 'exit 130' INT TERM HUP

banner "Cargar el keystore de EAS en GitHub"

# ── Etapa 1 ───────────────────────────────────────────────────────────────
stage "Requisitos"
say "Compruebo que esté todo lo necesario antes de tocar nada."
if [[ ! -f app.json ]]; then
  warn "No encuentro app.json: corré el script desde la raíz del repositorio."
  note "  cd ruta/a/AppCalculadora && bash scripts/cargar-keystore.sh"
  exit 1
fi
step "Estás en la raíz del repositorio (existe app.json)."
if ! command -v node >/dev/null 2>&1; then
  warn "No encuentro node. Instalá Node.js y volvé a correr el script."
  exit 1
fi
step "node disponible: $(node --version)"
if ! command -v gh >/dev/null 2>&1; then
  warn "No encuentro gh (GitHub CLI). Instalalo desde https://cli.github.com y volvé a correr."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "gh no tiene sesión iniciada. Corré 'gh auth login' y volvé a correr el script."
  exit 1
fi
step "gh con sesión iniciada."
REPO_DESTINO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
say ""
say "Los secrets se van a cargar en: ${BOLD}${REPO_DESTINO}${RESET}"
if ! confirm "¿Es el repositorio correcto?"; then
  warn "Cancelado: no se tocó nada."
  exit 1
fi

# ── Etapa 2 ───────────────────────────────────────────────────────────────
stage "Sesión de Expo (EAS)"
say "Reviso si hay una sesión de Expo iniciada (la primera vez npx baja eas-cli)."
USUARIO_EXPO=""
if USUARIO_EXPO=$(npx --yes eas-cli whoami 2>/dev/null) && [[ -n "$USUARIO_EXPO" ]] \
   && [[ "$USUARIO_EXPO" != *"Not logged in"* ]]; then
  step "Sesión iniciada como: $(printf '%s' "$USUARIO_EXPO" | head -n 1)"
else
  say "No hay sesión. Ahora se abre el login de Expo:"
  step "Usuario: ${BOLD}lagueb${RESET} (o el mail de esa cuenta)."
  step "Contraseña: la tuya de Expo. No se muestra mientras la escribís."
  pause "Enter para iniciar sesión…"
  npx --yes eas-cli login
  USUARIO_EXPO=$(npx --yes eas-cli whoami 2>/dev/null || true)
  step "Sesión iniciada como: $(printf '%s' "$USUARIO_EXPO" | head -n 1)"
fi
pause "Enter para seguir…"

# ── Etapa 3 ───────────────────────────────────────────────────────────────
stage "Bajar las credenciales de EAS"
if [[ -e "$CREDENCIALES_JSON" ]]; then
  warn "Ya existe $CREDENCIALES_JSON de una corrida anterior: se usa ése y se borra al final."
  _LIMPIEZA_ACTIVA=1
else
  say "Ahora se abre el menú de credenciales de EAS. Ahí adentro:"
  step "Si pregunta el perfil de build, elegí ${BOLD}apk${RESET}."
  step "Elegí la opción que menciona ${BOLD}credentials.json${RESET}."
  step "Después, ${BOLD}Download credentials from EAS to credentials.json${RESET}."
  note "  Si los textos del menú no son exactamente esos, elegí el equivalente:"
  note "  lo que importa es DESCARGAR las credenciales a credentials.json."
  step "Cuando diga que lo guardó, salí del menú (Go back / Exit, o Ctrl-C:"
  note "  acá Ctrl-C cierra sólo el menú de EAS, el asistente sigue)."
  pause "Enter para abrir el menú…"
  # Desde acá puede aparecer credentials.json: la trampa lo borra si el script se corta.
  _LIMPIEZA_ACTIVA=1
  # Mientras corre el menú, Ctrl-C cierra sólo eas-cli y el asistente sigue: una
  # trampa con comando (no vacía) vuelve a la acción por defecto en el proceso hijo.
  trap ':' INT
  npx --yes eas-cli credentials -p android || true
  trap 'exit 130' INT
fi

MODO_MANUAL=0
if [[ -f "$CREDENCIALES_JSON" ]]; then
  KEYSTORE_EAS=$(leer_credencial keystorePath || true)
  if [[ -z "$KEYSTORE_EAS" || ! -f "$KEYSTORE_EAS" ]]; then
    warn "credentials.json no apunta a un keystore existente ($KEYSTORE_EAS)."
    MODO_MANUAL=1
  else
    say ""
    step "Credenciales descargadas. Keystore en: $KEYSTORE_EAS"
  fi
else
  warn "No apareció credentials.json."
  MODO_MANUAL=1
fi

if (( MODO_MANUAL )); then
  say ""
  say "Camino manual: necesito el .jks que bajaste de EAS y sus datos."
  note "  Se bajan con: npx eas-cli credentials → Android → apk →"
  note "  Keystore → Download existing keystore (muestra alias y contraseñas)."
  if ! confirm "¿Tenés el .jks y los datos para seguir a mano?"; then
    warn "Cancelado: no se cargó ningún secret."
    exit 1
  fi
  while :; do
    ask KEYSTORE_MANUAL "Ruta del archivo .jks:"
    [[ -f "$KEYSTORE_MANUAL" ]] && break
    warn "No existe el archivo '$KEYSTORE_MANUAL'. Probá de nuevo."
  done
  ask_secret VALOR_KEYSTORE_PASSWORD "Contraseña del keystore (no se muestra):"
  ask VALOR_KEY_ALIAS "Alias de la clave:"
  ask_secret VALOR_KEY_PASSWORD "Contraseña de la clave (no se muestra):"
fi
pause "Enter para cargar los secrets…"

# ── Etapa 4 ───────────────────────────────────────────────────────────────
stage "Cargar los cuatro secrets en GitHub"
say "Los valores van por entrada estándar a 'gh secret set': no se muestran."
if (( MODO_MANUAL )); then
  ARCHIVO_KEYSTORE="$KEYSTORE_MANUAL"
else
  ARCHIVO_KEYSTORE="$KEYSTORE_EAS"
  VALOR_KEYSTORE_PASSWORD=$(leer_credencial keystorePassword) \
    || { warn "credentials.json no trae keystorePassword."; exit 1; }
  VALOR_KEY_ALIAS=$(leer_credencial keyAlias) \
    || { warn "credentials.json no trae keyAlias."; exit 1; }
  VALOR_KEY_PASSWORD=$(leer_credencial keyPassword) \
    || { warn "credentials.json no trae keyPassword."; exit 1; }
fi
VALOR_KEYSTORE_BASE64=$(base64 -w0 < "$ARCHIVO_KEYSTORE")
if [[ -z "$VALOR_KEYSTORE_BASE64" ]]; then
  warn "El keystore está vacío: no se cargó nada."
  exit 1
fi

# set_secret (librería) pasa cada valor por stdin con printf, que es interno de
# bash: el valor nunca aparece como argumento de un proceso.
set_secret ANDROID_KEYSTORE_BASE64 "$VALOR_KEYSTORE_BASE64"
set_secret ANDROID_KEYSTORE_PASSWORD "$VALOR_KEYSTORE_PASSWORD"
set_secret ANDROID_KEY_ALIAS "$VALOR_KEY_ALIAS"
set_secret ANDROID_KEY_PASSWORD "$VALOR_KEY_PASSWORD"
unset VALOR_KEYSTORE_BASE64 VALOR_KEYSTORE_PASSWORD VALOR_KEY_ALIAS VALOR_KEY_PASSWORD
pause "Enter para limpiar y verificar…"

# ── Etapa 5 ───────────────────────────────────────────────────────────────
stage "Limpieza y verificación"
if (( MODO_MANUAL )); then
  say "El .jks contiene la clave de firma de la app: ya está en GitHub."
  if confirm "¿Borro $KEYSTORE_MANUAL de la PC?"; then
    rm -f "$KEYSTORE_MANUAL"
    step "Borrado: $KEYSTORE_MANUAL"
  else
    note "  Quedó en $KEYSTORE_MANUAL. Guardalo fuera del repositorio."
  fi
fi
if (( _LIMPIEZA_ACTIVA )) && [[ -e "$CREDENCIALES_JSON" || ( -n "$KEYSTORE_EAS" && -e "$KEYSTORE_EAS" ) ]]; then
  say "credentials.json y el keystore de EAS tienen las contraseñas en texto plano."
  if confirm "¿Los borro ahora? (recomendado)"; then
    _borrar_credenciales_eas
    step "Borrados credentials.json y el keystore descargado."
  else
    _CONSERVAR_ARCHIVOS=1
    warn "Quedaron en disco. No los commitees (están en .gitignore) y borralos cuando puedas."
  fi
fi

say ""
say "Secrets presentes en ${REPO_DESTINO} (GitHub sólo muestra los nombres):"
PRESENTES=$(gh secret list --json name -q '.[].name' 2>/dev/null || true)
FALTAN=0
for nombre in "${SECRETS_APK[@]}"; do
  if grep -qx "$nombre" <<< "$PRESENTES"; then
    step "$nombre ✓"
  else
    warn "$nombre falta"
    FALTAN=1
  fi
done
say ""
if (( FALTAN )); then
  warn "Falta algún secret: revisá los avisos de arriba y volvé a correr el script."
else
  say "${GREEN}Listo: ya podés avisarle al agente que los secrets están cargados.${RESET}"
fi
pause "Enter para terminar…"

finish
}

run_wizard "$@"; exit

